\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{booktabs}
\usepackage{array}
\usepackage{colortbl}
\pagestyle{empty}

% ── Dark Navy Color Theme ──
\definecolor{primary}{HTML}{0A1628}
\definecolor{secondary}{HTML}{1E3A5F}
\definecolor{accent}{HTML}{00B4D8}
\definecolor{accentgreen}{HTML}{06D6A0}
\definecolor{accentyellow}{HTML}{FFD166}
\definecolor{bgposter}{HTML}{0D1B2A}
\definecolor{bgcard}{HTML}{112233}
\definecolor{bgcardalt}{HTML}{0F1E30}
\definecolor{textlight}{HTML}{E8F4FD}
\definecolor{textmid}{HTML}{94A3B8}
\definecolor{textdark}{HTML}{F1F5F9}
\definecolor{rowalt}{HTML}{152840}
\definecolor{rowhead}{HTML}{00B4D8}
\definecolor{starburst}{HTML}{FF6B6B}
\definecolor{greenlight}{HTML}{0A2E22}

\pagecolor{bgposter}
\color{textdark}

\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=0pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}

\tcbset{
  navycard/.style={
    enhanced, arc=4pt, boxrule=1pt,
    colframe=accent!40, colback=bgcard,
    left=22pt, right=22pt, top=12pt, bottom=12pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=secondary,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=1pt, titlerule style={accent!50},
    valign=top,
  },
  greencard/.style={
    enhanced, arc=4pt, boxrule=1pt,
    colframe=accentgreen!40, colback=greenlight,
    left=22pt, right=22pt, top=12pt, bottom=12pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accentgreen},
    coltitle=accentgreen, colbacktitle=primary,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=1pt, titlerule style={accentgreen!50},
    valign=top,
  },
  accentcard/.style={
    enhanced, arc=4pt, boxrule=1pt,
    colframe=accentyellow!50, colback=bgcardalt,
    left=22pt, right=22pt, top=12pt, bottom=12pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accentyellow},
    coltitle=accentyellow, colbacktitle=primary,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=1pt, titlerule style={accentyellow!50},
    valign=top,
  },
  herocard/.style={
    enhanced, arc=6pt, boxrule=2pt,
    colframe=accent, colback=secondary,
    left=24pt, right=24pt, top=14pt, bottom=14pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=accent,
    toptitle=12pt, bottomtitle=12pt,
    titlerule=0pt,
    valign=top,
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=24, spacing=3mm},
]

% ══════════════════════════════
% TITLE BAR  rows 1-3
% ══════════════════════════════
\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=primary,
  left=36pt, right=36pt, top=20pt, bottom=20pt,
  halign=center, valign=center,
  borderline south={4pt}{0pt}{accent},
]{name=titlebar, column=1, span=3, between=top and row3}{%
  {\fontsize{24}{30}\selectfont\bfseries\color{textmid}%
    EPAM SYSTEMS\enspace\textbf{\color{accent}OSCI}\enspace REPORT
    \enspace|\enspace MARCH 2026}\\[8pt]
  {\fontsize{78}{90}\selectfont\bfseries\color{textlight}%
    Open Source Contributor Index}\\[6pt]
  {\fontsize{36}{44}\selectfont\color{textmid}%
    Corporate GitHub Contributions\quad
    \textbf{\color{accentgreen}— Ranked \& Tracked}}%
}

% ══════════════════════════════
% STAT BANNER  rows 3-5
% ══════════════════════════════
\posterbox[
  enhanced, arc=0pt, boxrule=0pt, colback=secondary,
  left=16pt, right=16pt, top=0pt, bottom=0pt,
  borderline south={2pt}{0pt}{accent!40},
]{name=statbanner, column=1, span=3, between=row3 and row5}{%
  \vspace{8pt}
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \tcbox[enhanced, arc=4pt, boxrule=1pt, colframe=accent!60,
      colback=bgcard, left=12pt, right=12pt, top=10pt, bottom=10pt]{%
      {\fontsize{66}{80}\selectfont\bfseries\color{accent} 239}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{textmid} Organizations Tracked}%
    }
  \end{minipage}\hfill
  \begin{minipage}[c]{0.36\linewidth}\centering
    \tcbox[enhanced, arc=4pt, boxrule=2pt, colframe=starburst!80,
      colback=secondary, left=12pt, right=12pt, top=10pt, bottom=10pt]{%
      {\fontsize{66}{80}\selectfont\bfseries\color{starburst} 548}\\[4pt]
      {\fontsize{28}{34}\selectfont\bfseries\color{accentgreen}
        $\uparrow$\,+128 MoM}\quad
      {\fontsize{26}{32}\selectfont\color{textmid} Google \#1}%
    }
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \tcbox[enhanced, arc=4pt, boxrule=1pt, colframe=accentgreen!60,
      colback=bgcard, left=12pt, right=12pt, top=10pt, bottom=10pt]{%
      {\fontsize{66}{80}\selectfont\bfseries\color{accentgreen} 2{,}721}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{textmid} Top-10 Combined Active}%
    }
  \end{minipage}%
  \vspace{8pt}
}

% ══════════════════════════════
% LEADERBOARD — rows 5-17
% ══════════════════════════════
\posterbox[herocard, title={%
  \raisebox{-2pt}{$\bigstar$}\enspace
  Top 10 Organizations by Active Contributors — March 2026}
]{name=leaderboard, column=1, span=3, between=row5 and row17}{%
  \fontsize{32}{42}\selectfont
  \renewcommand{\arraystretch}{1.65}
  \begin{tabular*}{\linewidth}{@{\hspace{10pt}}c@{\hspace{16pt}}l@{\extracolsep{\fill}}r@{\hspace{20pt}}r@{\hspace{20pt}}r@{\hspace{20pt}}r@{\hspace{10pt}}}
    \rowcolor{accent}
    {\color{white}\bfseries Rank} &
    {\color{white}\bfseries Organization} &
    {\color{white}\bfseries Active} &
    {\color{white}\bfseries MoM $\Delta$} &
    {\color{white}\bfseries Community} &
    {\color{white}\bfseries MoM $\Delta$} \\[4pt]
    %
    \rowcolor{starburst!30}
    {\color{accentyellow}\bfseries\#1} & {\color{textlight}\bfseries Google} &
    {\color{starburst}\bfseries 548} &
    {\color{accentgreen}\bfseries $\uparrow$\,+128} &
    {\color{textlight}\bfseries 1{,}986} &
    {\color{accentgreen}\bfseries $\uparrow$\,+267} \\
    %
    \rowcolor{rowalt}
    {\color{textmid}\bfseries\#2} & {\color{textlight} Microsoft} &
    438 & {\color{accentgreen} $\uparrow$\,+74} & 1{,}189 & {\color{accentgreen} $\uparrow$\,+174} \\
    %
    {\color{textmid}\bfseries\#3} & {\color{textlight} Red Hat} &
    432 & {\color{accentgreen} $\uparrow$\,+94} & 1{,}378 & {\color{accentgreen} $\uparrow$\,+193} \\
    %
    \rowcolor{rowalt}
    {\color{textmid}\bfseries\#4} & {\color{textlight} AMD} &
    233 & {\color{accentgreen} $\uparrow$\,+66} & 627 & {\color{accentgreen} $\uparrow$\,+109} \\
    %
    {\color{textmid}\bfseries\#5} & {\color{textlight} Datadog} &
    221 & {\color{accentgreen} $\uparrow$\,+34} & 411 & {\color{accentgreen} $\uparrow$\,+58} \\
    %
    \rowcolor{rowalt}
    {\color{textmid}\bfseries\#6} & {\color{textlight} Intel} &
    217 & {\color{accentgreen} $\uparrow$\,+48} & 707 & {\color{accentgreen} $\uparrow$\,+82} \\
    %
    {\color{textmid}\bfseries\#7} & {\color{textlight} NVIDIA} &
    194 & {\color{accentgreen} $\uparrow$\,+41} & 650 & {\color{accentgreen} $\uparrow$\,+106} \\
    %
    \rowcolor{rowalt}
    {\color{textmid}\bfseries\#8} & {\color{textlight} SUSE} &
    158 & {\color{accentgreen} $\uparrow$\,+32} & 353 & {\color{accentgreen} $\uparrow$\,+51} \\
    %
    {\color{textmid}\bfseries\#9} & {\color{textlight} IBM} &
    140 & {\color{accentgreen} $\uparrow$\,+44} & 616 & {\color{accentgreen} $\uparrow$\,+133} \\
    %
    \rowcolor{rowalt}
    {\color{textmid}\bfseries\#10} & {\color{textlight} SAP} &
    140 & {\color{accentgreen} $\uparrow$\,+34} & 378 & {\color{accentgreen} $\uparrow$\,+54} \\
  \end{tabular*}
  \vspace{10pt}
  \par
  {\fontsize{28}{36}\selectfont\color{textmid}%
    \textbf{\color{accentgreen}$\uparrow$ Every} organization in the Top 10 posted positive
    month-over-month growth.
    \quad Combined active-contributor gain: \textbf{\color{accentgreen}+595 MoM.}
    \quad Google alone: \textbf{\color{starburst}+128} — the largest single-org gain.}%
}

% ══════════════════════════════
% COL 1: PROGRAMMING LANGUAGES  rows 17-23
% ══════════════════════════════
\posterbox[navycard, title={Top Programming Languages}
]{name=langs, column=1, span=1, between=row17 and row23}{%
  \fontsize{32}{42}\selectfont
  \renewcommand{\arraystretch}{1.75}
  \begin{tabular*}{\linewidth}{@{}l@{\extracolsep{\fill}}r@{}}
    \colorbox{accent!80}{\color{white}\bfseries~~Python~~} &
      {\color{accent}\bfseries 20.3\%} \\
    \colorbox{accentgreen!55}{\color{bgcard}\bfseries~~C++~~} &
      {\color{accentgreen} 14.3\%} \\
    \colorbox{accent!50}{\color{white}~~Go~~} &
      {\color{accent} 11.6\%} \\
    \colorbox{accentyellow!55}{\color{bgcard}~~C~~} &
      {\color{accentyellow} 10.9\%} \\
    \colorbox{accent!35}{\color{white}~~TypeScript~~} &
      {\color{accent} 10.5\%} \\
    \colorbox{textmid!25}{\color{textlight}~~Java~~} &
      {\color{textmid} 4.4\%} \\
  \end{tabular*}
  \vspace{10pt}
  \par{\fontsize{28}{36}\selectfont\color{textmid}%
    \textbf{\color{accent}Python} leads decisively —
    dominant in AI/ML, data science, and cloud-native tooling.
    Systems languages (C++ \& C) total \textbf{25.2\%}, reflecting
    critical infra projects.}%
}

% ══════════════════════════════
% COL 2: GROWTH MOMENTUM  rows 17-23
% ══════════════════════════════
\posterbox[greencard, title={Monthly Growth Momentum}
]{name=growth, column=2, span=1, between=row17 and row23}{%
  \fontsize{32}{42}\selectfont
  \tcbox[enhanced, arc=3pt, boxrule=1pt,
    colframe=accentgreen!50, colback=primary,
    left=12pt, right=12pt, top=8pt, bottom=8pt]{%
    \centering
    {\fontsize{58}{70}\selectfont\bfseries\color{accentgreen} +595}\\[2pt]
    {\fontsize{28}{36}\selectfont\color{textmid} Combined Top-10 Active-Contributor Gain}
  }\vspace{10pt}
  \par
  \begin{itemize}[itemsep=12pt]
    \item \textbf{\color{textlight}Google} added \textbf{\color{accentgreen}+128}
      active contributors — largest single gain
    \item \textbf{\color{textlight}IBM} grew \textbf{\color{accentgreen}$\approx$46\%} MoM:
      +44 active, +133 community
    \item \textbf{\color{textlight}Red Hat} +94 active, +193 community —
      momentum rivaling Microsoft
    \item \textbf{100\%} of Top-10 orgs \textbf{\color{accentgreen}accelerating} —
      zero declines recorded
  \end{itemize}%
}

% ══════════════════════════════
% COL 3: ECOSYSTEM SCALE & LICENSES  rows 17-23
% ══════════════════════════════
\posterbox[accentcard, title={Ecosystem Scale \& Licensing}
]{name=ecosystem, column=3, span=1, between=row17 and row23}{%
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item \textbf{\color{accentyellow}239} commercial organizations tracked globally
    \item Top-10 total community: \textbf{\color{textlight}8{,}295} contributors
    \item Google's community: \textbf{\color{starburst}1{,}986} (+267 MoM)
  \end{itemize}
  \vspace{8pt}
  {\fontsize{30}{38}\selectfont\bfseries\color{textmid} License Landscape:}
  \vspace{4pt}
  \renewcommand{\arraystretch}{1.65}
  \begin{tabular*}{\linewidth}{@{\hspace{4pt}}c@{\hspace{12pt}}l@{}}
    {\color{accentyellow}\bfseries 1.} & \textbf{Apache-2.0}
      \;\textit{\color{textmid}(most prevalent)} \\
    {\color{textmid} 2.} & MIT \\
    {\color{textmid} 3.} & GPL-2.0 \\
    {\color{textmid} 4.} & Other permissive / copyleft \\
  \end{tabular*}
  \vspace{10pt}
  \par{\fontsize{28}{36}\selectfont\color{textmid}%
    Apache-2.0 \& MIT dominate — reflecting
    enterprise-friendly, permissive licensing trends.}%
}

% ══════════════════════════════
% FOOTER  rows 23-bottom
% ══════════════════════════════
\posterbox[
  enhanced, arc=0pt, boxrule=0pt, colback=primary,
  left=36pt, right=36pt, top=10pt, bottom=10pt,
  halign=center, valign=center,
  borderline north={3pt}{0pt}{accent!60},
]{name=footer, column=1, span=3, between=row23 and bottom}{%
  {\fontsize{27}{34}\selectfont\color{textmid}%
    Data source: GitHub\enspace·\enspace
    Tracked period: Year-to-date through March 31, 2026
    \enspace·\enspace\textbf{\color{accent}osci.epam.com}
    \enspace·\enspace OSCI is open source — GPL v3.0}%
}

\end{tcbposter}
\end{document}

